from pathlib import Path
import re,json
root=Path(__file__).resolve().parents[1]
history='''<section class="page-section" id="histoire"><p class="eyebrow">Une histoire commencée en 1986</p><h2>Une entreprise.<br>Une histoire de transmission.</h2><p class="page-lead">Avant d’être une histoire de famille, ABK est une histoire de métier, de confiance et de piscines pensées pour durer.</p><div class="history-timeline"><article><strong>1986</strong><h3>Le début de l’histoire.</h3><p>L’entreprise est créée en 1986 par Jacques Tournabien. Au fil des chantiers, un savoir-faire se construit autour de la création, de la rénovation et de la vie des piscines.</p></article><article><strong>Stéphane</strong><h3>Le « MacGyver de la piscine ».</h3><p>D’abord salarié de l’entreprise, Stéphane se fait remarquer par sa capacité à trouver des solutions. Son patron le surnomme le « MacGyver de la piscine ». Il reprend ensuite l’entreprise et poursuit son développement.</p></article><article><strong>Aujourd’hui</strong><h3>Karine et Benjamin, une même vision.</h3><p>Karine, la femme de Stéphane, et son frère Benjamin ont repris l’entreprise il y a quelques années. Frère et sœur à la tête d’ABK, ils prolongent cette aventure familiale, avec Stéphane à leurs côtés pour la partie technique.</p></article></div><p class="history-quote">« De votre rêve à sa réalisation. »</p><p>La création de bassins, leur rénovation, la pose de membranes armées, l’entretien, la mise en route et l’hivernage font partie du quotidien de l’équipe. Les terrasses, les pool-houses et les locaux techniques relient le bassin à son environnement.</p></section>'''
press='''<section class="page-section" id="presse"><p class="eyebrow">Dans la presse</p><h2>Une rencontre devenue un article.</h2><p class="page-lead">Un journaliste, lui-même client, a découvert l’équipe et son travail. De cette rencontre est né ce portrait d’ABK, de Karine, de Benjamin et de leur manière d’accompagner les projets.</p><p>« De votre rêve à sa réalisation » · J. Simon · Vidici, septembre 2026 · Infomercial.</p><figure class="press-reader" aria-label="Article Vidici sur ABK : survolez ou déplacez le doigt pour lire à la loupe"><img src="public/presse/vidici-septembre-2026-1.webp" width="1600" height="2200" alt="Article Vidici de septembre 2026, signé J. Simon : portrait de Karine et Benjamin à la tête d’ABK Bâti & Piscine" loading="lazy" draggable="false"></figure><p class="press-hint">Sur ordinateur, survolez l’article pour lire à la loupe. Sur mobile ou tablette, posez le doigt sur l’article puis déplacez-le.</p></section>'''
gallery='''<section class="pool-realizations" id="realisations-piscine"><header><div><p class="eyebrow">Nos réalisations en images</p><h2>Un chantier, plusieurs regards.</h2><p>Chaque vignette ouvre les photos d’un seul projet. Parcourez les réalisations ou explorez les différentes étapes d’un même chantier.</p></div><div class="gallery-arrows"><button type="button" data-project-prev aria-label="Projets précédents">←</button><button type="button" data-project-next aria-label="Projets suivants">→</button></div></header><div data-project-gallery="public/realisations/projects.json"></div></section>'''
for name in ['index.html','a-propos.html','piscines-exterieurs.html','bati-renovation.html','pac-incendie.html']:
 p=root/name;s=p.read_text(encoding='utf8')
 if 'media-enhancements.css' not in s:s=s.replace('</head>','<link rel="stylesheet" href="media-enhancements.css"><script src="media-protection.js" defer></script><script src="partnership.js" defer></script></head>')
 if name=='piscines-exterieurs.html':
  s=s.replace('src="public/hero-villa.png" alt="Piscine et terrasse ouvertes sur le jardin"','src="public/realisations/piscine-terrasse-bois-hero.webp" alt="Réalisation ABK : piscine au cœur d’une terrasse en bois, entre maison et jardin"')
  if 'data-project-gallery' not in s:s=s.replace('</main>',gallery+'</main><script src="project-gallery.js" defer></script>')
  s=s.replace('<a href="#questions">Questions utiles</a>','<a href="#questions">Questions utiles</a><a href="#realisations-piscine">Nos réalisations</a>')
 if name=='a-propos.html' and 'id="histoire"' not in s:
  s=s.replace('</section>','</section>'+history,1).replace('<section class="page-cta">',press+'<section class="page-cta">')
  s=s.replace('<a class="button primary" href="index.html#prestations">Découvrir nos expertises</a>','<a class="button primary" href="#histoire">Notre histoire</a><a href="#presse">Dans la presse</a>')
 if name=='bati-renovation.html' and 'data-project-gallery' not in s:s=s.replace('</main>',gallery.replace('realisations-piscine','realisations-bati').replace('Nos réalisations en images','Sur le chantier').replace('public/realisations/projects.json','public/realisations/build-projects.json')+'</main><script src="project-gallery.js" defer></script>')
 canonical='https://abk-ten.vercel.app/'+('' if name=='index.html' else name.replace('.html',''))
 if 'rel="canonical"' not in s:s=s.replace('</head>',f'<link rel="canonical" href="{canonical}"></head>')
 title=re.search(r'<title>(.*?)</title>',s).group(1);desc=re.search(r'<meta name="description" content="([^"]+)"',s)
 description=desc.group(1) if desc else 'Depuis 1986, une histoire de métier et de transmission. Découvrez ABK, Karine, Benjamin, Stéphane et le portrait publié dans Vidici.'
 if not desc:s=s.replace('</head>',f'<meta name="description" content="{description}"></head>')
 if 'property="og:title"' not in s:s=s.replace('</head>',f'<meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><meta property="og:url" content="{canonical}"><meta property="og:type" content="website"><meta property="og:image" content="https://abk-ten.vercel.app/public/realisations/piscine-terrasse-bois-hero.webp"><meta name="twitter:card" content="summary_large_image"></head>')
 if name=='a-propos.html' and 'application/ld+json' not in s:
  data={'@context':'https://schema.org','@type':'AboutPage','name':'L’histoire d’ABK Bâti & Piscine','url':canonical,'about':{'@type':'Organization','name':'ABK Bâti & Piscine','foundingDate':'1986','url':'https://abk-ten.vercel.app','telephone':'+33546057292','email':'info@abk-piscine.fr','address':{'@type':'PostalAddress','streetAddress':'62 ter rue François Arago','postalCode':'17200','addressLocality':'Royan','addressCountry':'FR'}}}
  s=s.replace('</head>','<script type="application/ld+json">'+json.dumps(data,ensure_ascii=False)+'</script></head>')
 p.write_text(s,encoding='utf8')
print('Public pages updated.')
